      "content": "import pytest
from glom import glom, T, Spec
from glom.core import register_op


def test_register_op_custom_spec():
    class DoubleKey:
        def __init__(self, key):
            self.key = key

    @register_op(DoubleKey)
    def _handle_double_key(*args, **kwargs):
        if len(args) == 3:
            target, spec, scope = args
        elif len(args) == 1:
            scope = args[0]
            target, spec = scope[T], scope[Spec]
        else:
            target, spec = args[:2]
        return target[spec.key] * 2

    target = {"count": 21}
    result = glom(target, DoubleKey("count"))
    assert result == 42
